pub(super) fn known(module: &str, name: &str) -> bool {
    let names = match module {
        "arm" => ARM,
        "aarch64" => AARCH64,
        "x86" => X86,
        "x86_64" => X86_64,
        "wasm32" => WASM32,
        _ => return false,
    };
    names.binary_search(&name).is_ok()
}
